const escapeHtml=value=>String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]));
const shortId=value=>value?String(value).slice(0,8):"—";
const actionLabels={teacher_approval_changed:"Öğretmen durumu değişti",teacher_partner_upserted:"Partner profili güncellendi",payment_approved:"Ödeme onaylandı",payment_rejected:"Ödeme reddedildi",commission_payout_created:"Payout oluşturuldu",commission_payout_cancelled:"Payout iptal edildi",commission_payout_paid:"Payout ödendi"};
const entityLabels={teacher_profile:"Öğretmen",teacher_partner_profile:"Partner",payment_request:"Ödeme",commission_payout:"Payout"};
const filters=[["all","Tümü"],["payments","Ödemeler"],["teachers","Öğretmenler"],["partners","Partnerler"],["payouts","Payout'lar"]];
const date=value=>value?new Intl.DateTimeFormat("tr-TR",{dateStyle:"short",timeStyle:"short"}).format(new Date(value)):"—";
function transition(row){const before=row.old_values?.status||row.old_values?.approval_status,after=row.new_values?.status||row.new_values?.approval_status;return before||after?`${escapeHtml(before||"—")} → ${escapeHtml(after||"—")}`:"—"}
export function adminAuditView(rows=[],activeFilter="all"){return `<section class="card" data-admin-audit-log><h2>Yönetici İşlem Geçmişi</h2><div class="button-row" role="group" aria-label="İşlem geçmişi filtresi">${filters.map(([value,label])=>`<button type="button" class="button ${activeFilter===value?"primary":"secondary"}" data-audit-filter="${value}">${label}</button>`).join("")}</div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Tarih</th><th>İşlem</th><th>Varlık</th><th>Yönetici</th><th>Durum</th><th>Not</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${date(row.created_at)}</td><td>${escapeHtml(actionLabels[row.action]||row.action)}</td><td>${escapeHtml(entityLabels[row.entity_type]||row.entity_type)} · ${escapeHtml(shortId(row.entity_id))}</td><td>${escapeHtml(shortId(row.actor_user_id))}</td><td>${transition(row)}</td><td>${escapeHtml(row.new_values?.admin_note||row.metadata?.admin_note||"—")}</td></tr>`).join("")}</tbody></table></div>`:"<p>Bu filtre için işlem kaydı yok.</p>"}</section>`}
